      long rl = fr ? (long)fread(rom, 1, sizeof rom, fr) : 0;
      if (fw) { size_t n = fread(wr, 1, sizeof wr, fw); (void)n; }
      if (fr) fclose(fr); if (fw) fclose(fw);
      int loc = (int)strtol(argv[i + 2], NULL, 16);
