        int loc = w[0x0100] | (w[0x0101] << 8);
        printf("loadcheck: slot=%d bytes=0x%04X loc=%04X tile(%d,%d) bits=%02X party=%02X%02X%02X "
               "gold=%d storyline=%02X save#=%d era='%s' chapter='%s'\n",
               k, n, loc, w[0x0102], w[0x0103], w[0x0104], w[0x2980], w[0x2981], w[0x2982],
               w[0x2C53] | (w[0x2C54] << 8) | (w[0x2C55] << 16), w[0x10000],
               w[0x299C] | (w[0x299D] << 8), CtMenuLoaderEra(loc), CtMenuLoaderChapter(w[0x10000], 1));
