  int menuItemPopCurve = -1, menuItemPopPool = 0, menuItemPopBits = 0;   // C2/9016: FF/CEBA index, 1 HP / 2 MP, $0F5D
  int menuItemPopAmt[3][2];                                  // C2/8E82 / C2/8EAB's numbers per party slot
  int menuItemB31C = 0;                                      // the pop-up is over: C2/B31C next frame
  int menuItemTabX = 0;                                      // a Tab's `$0DBD` (C2/B200): C2/B2E0 runs before C2/B31C
  int menuItemAllTask = 0;                                   // task slot 6 = C2/8AFD, an all-party item's three hands
  int menuNavHandOk = 1;                                     // C2/E954: this frame's nav hand ($0D9B was 0)
  long menuItemPopPal = 0x3FCB9CL;                           // the pop-up's colours: C2/8F55 FF/CB9C, C2/B2A7 FF/CBAC
  int menuItemPinTask = 0;                                   // task slot 6 = C2/89F2, the picked row's blinking hand
  int menuFormPickTask = 0;                                  // task slot 6 = C2/8A45, the Form's picked panel's hand
  int menuFormAnimReq = 0;                                   // C2/C805 ran this frame: its C2/C840 JSR C2/C973;
                                                             //   -1 = C2/C6E7's STZ $1811 for all seven (all still)
  int menuItemAAFF = 0;                                      // C2/AAFF yielded: the next frame redraws the rows, $68 := 2
  uint8_t* menuFb = (uint8_t*)malloc((size_t)CAMW * CAMH * 3);
  struct {                         // the C0/011B save block, mirrored on the live values:
    int valid;                     //   $0102-4 lead tile/facing (written into the $7E image),
    double px, py;                 //   $7F1D09/0F = 3x PC pixel pos, $7F1D15 = the $0C00 prio pairs.
    int pz, pfac;                  //   The camera is not saved here: it lives in the VM mem.s
    int pcObj[3], pcX[3], pcY[3];  //   ($1D0A/$1D0E/$1D93/$1D96), which the menu freeze holds untouched
    uint8_t pcPrio[3][2];          //   (field_camera_unification.md G.2).
    uint8_t party[3];              //   ...and $0194-0196, the party shadow C0/1A1B compares on the way out.
  } mSave;
  memset(&mSave, 0, sizeof mSave);
