  memset(&mtPre, 0, sizeof mtPre); memset(&mtPost, 0, sizeof mtPost);
  int mtNp = 0, mtDataOk = 0, mtResumeOk = 0; uint32_t mtFnv = 0;
  int mtItemOk = 0;                // scripted Right+A -> Item screen decodes "Pendant" + B returns
  int mtStatusOk = 0;              // scripted Left+A+A -> Status screen 1 detail decodes correctly
  int mtTechOk = 0;                // scripted RR+A+A -> Tech screen 3 lists Crono's learned singles
  int mtConfigOk = 0;              // scripted R+A -> Config screen 4 decodes the settings list
  int mtFormOk = 0;                // scripted R+A+pick0+Down+pick1 -> Form swap $2980 00,01->01,00
  int mtSaveOk = 0;                // scripted R+A -> Save screen 6 reads the 3 SRAM slots (all empty)
  int mtHp[4] = {0,0,0,0};         // Crono cur/max, Marle cur/max (for the verdict line)
  int btBattleFrame = 0;           // --battletest: the frame the battle module ran (0 = not yet)
  int battleResolved = 0, battleResolveFrame = 0;  // set the frame an interactive battle hands back (battlePhase
