  int pendWX = 0, pendWY = 0;                                              // overworld destination pixels
  uint8_t pendFlags[0x200];
  int selftestFrames = (tframes > 0) ? tframes : (talkObj >= 0 ? 50 : 1);  // --frames honored; talk default 50
  // dialogue paging + typewriter state (per open box)
  const char* tbStr = NULL; int tbStrLen = 0, tbPage = 0, tbReveal = 0, tbN = 1;
  int tbLastIdx = -1, tbLastTbl = -2, tbPageStart[40];
  // plain text uses the line model (smooth scroll); choices keep the page model
