            int cyc = (seqR[0]==1 && seqR[1]==2 && seqR[2]==3 && seqR[3]==4 && seqR[4]==5 && seqR[5]==0);
            int lw = CtMenuRibbonStep(0, -1);                 // Left from opt0 wraps -> 5
